START TRANSACTION;
UPDATE stock SET quantity = 0 WHERE item_id = 1;
ROLLBACK;
SELECT item_id,quantity FROM stock ORDER BY item_id;

START TRANSACTION;
UPDATE stock SET quantity = quantity + 2 WHERE item_id = 1;
SAVEPOINT after_primary;
UPDATE stock SET quantity = quantity + 5 WHERE item_id = 2;
ROLLBACK TO SAVEPOINT after_primary;
COMMIT;
SELECT item_id,quantity FROM stock ORDER BY item_id;
